// === 🖼️ VIEW BASE64 IMAGE ===
const item = items[0].json;
const base64String = item.base64_img_string;

if (!base64String) {
    throw new Error("No image data found. The Artist agent likely failed to parse the output.");
}

// Default to png, but use dynamic type if available
const mime = item.base64_img_string_mime || "image/png";
const ext = mime.split('/')[1] || "png";

return [{
    json: item, 
    binary: {
        data: {
            data: base64String,
            mimeType: mime,
            fileExtension: ext,
            fileName: `generated_image.${ext}`
        }
    }
}];

// 1. Grab the ADK envelope
const {
  config,
  session_state: sessionState = {},
  session_events: sessionEvents = []
} = items[0].json;

// 2. Normalize the booleans (parsed fields live in session_state now)
const hasMath = sessionState.math_found === true;
const hasVisual = sessionState.image_request_found === true;

// 3. The Decision Logic — payload formatting (problem/description/status) is
//    handled by the per-branch no_model format_* tasks, so we ONLY pick a route.
let validation_route = "neither";
if (hasMath && hasVisual) validation_route = "ready";
else if (hasMath) validation_route = "math_only";
else if (hasVisual) validation_route = "visual_only";

// 4. Envelope through untouched; validation_route rides at top level for the Switch.
return [{
  json: {
    validation_route,
    config,
    session_state: sessionState,
    session_events: sessionEvents
  }
}];

// =============================================================================
// 📦 FINAL BROADCAST CONTRACT — the completion payload for the GUI stack.
// "Phase 6 - Output" carries ONLY { config, session_state, session_events };
// everything else is assembled HERE from direct node references. This node is
// the single source of truth for what ships on completion.
//
// NAMING: the Firestore doc's working transcript (built turn by turn from nodes
// 1 & 3's per-event broadcasts) is `session_events_incremental`. The FINISHED
// transcript — this payload's `session_events` — is what ends up in the bucket
// as {job_id}/session_events.json.
//
// DELIVERABLES and who consumes them:
//   ritel-state-manager/main.py (/update-state → Firestore + GCS bucket):
//    1. job_id                              REQUIRED — Firestore doc key
//    2. status: "completed"                 routes the final image, deletes
//                                           {job_id}/latest.png, and — as a
//                                           terminal status — triggers the listener
//                                           to materialize {job_id}/session_events.json
//                                           from the doc's session_events_incremental
//    3. base64_img_string (+ 4. _mime)      final render → {job_id}/final_illustration.png
//    5. session_events                      one-shot finished transcript. NOT stored
//                                           in the doc (listener pops it): fallback
//                                           transcript source + debug cross-check
//                                           against session_events_incremental
//                                           ("TRANSCRIPT MISMATCH" in Cloud Run
//                                           logs on divergence).
//    6. total_cost                          top-level realtime field; node 3 already
//                                           ships the running total every turn —
//                                           this is the same sum, finalized
//   ritel-frontend/app.py (via the Firestore doc; it renders
//   session_events_incremental — the one-shot copy never reaches the doc):
//    7. user_message                        chat panel (st.info)
//    8. archival_report                     zip download: archival_report.txt
//    9. latest_description                  metadata panel
//   10. original_query                      metadata panel
//   (+ generation_successful, timestamp, and the "-" phase/agent/task markers,
//    which the frontend shows as generic metadata / completion state)
//
//   NOTE: scaffolding is NOT shipped here anymore — "Archive Scaffolding" pins
//   {job_id}/scaffolding.png at the end of Phase 3 (real render or placeholder),
//   and re-sending the same bytes doubled this payload for nothing.
//
// ⚠️ NEVER include `config` (contains api_keys) or api keys in the payload —
//    the listener merges the entire payload into the Firestore job doc.
// ⚠️ LOAD-BEARING, not fire-and-forget (same policy as nodes 1 & 3 now): if this
//    POST fails, Firestore never learns the run completed — no final image, no
//    transcript materialization, a zombie "running" doc — while the workflow
//    would return a phantom "Workflow Complete". So a failure STOPS the run.
// ⚠️ NEVER reach back by name with a bare .first()/.last()/.all(). Those pick the
//    ITEM; the RUN is the second argument, and omitting it lets n8n choose — it
//    resolves against THIS node's run index (0, since this node runs once), so on
//    any retry loop you silently read the FIRST, REJECTED attempt. .item resolves
//    the run correctly but doesn't exist in "Run Once for All Items" mode. Hence
//    latestRun(): walk the runs and keep the last one that produced data.
// =============================================================================

const latestRun = (nodeName) => {
    let latest = null;
    for (let run = 0; run < 50; run++) {   // cap is a sanity guard; real loops max at 3
        let data;
        try { data = $(nodeName).all(0, run); }
        catch (e) { break; }               // past the last run, or node never executed
        if (data && data.length) latest = data[data.length - 1].json;
    }
    return latest;                         // null = node never ran on this path
};

const { config = {}, session_state: ss = {}, session_events: rawEvents = [] } =
    latestRun('Phase 6 - Output') || {};

// === 🏷️ RUN SETTINGS — launch choices baked into the config and otherwise lost ===
// "Resume final review" (Resume: Load Job) reads the LAST run_settings event to rebuild
// the config with the same style. Author "run_settings" is in no agent's history_scope,
// so no agent ever sees it.
const runSettingsEvent = {
    author: "run_settings",
    task: "run_settings",
    status: "ok",
    parts: [{ text: JSON.stringify({
        style_preference: config.style_preference ?? null,
        max_text_tier: config.maximum_text_tier ?? null,
        max_image_tier: config.maximum_image_tier ?? null
    }) }],
    timestamp: new Date().toISOString(),
    model: "none",
    cost: 0
};
const events = [...rawEvents, runSettingsEvent];

// Final render (artist output). Null-safe: nulls if the node never ran.
const artistJson = latestRun('artist - render_final');
const finalRender = {
    img:  artistJson?.base64_img_string || null,
    mime: artistJson?.base64_img_string_mime || null
};

// === 💸 TOTAL COST — sum of per-event model costs in the transcript ===
const totalCost = Number(
    events.reduce((sum, ev) => sum + (ev.cost || 0), 0).toFixed(6)
);

const finalPayload = {
    job_id: config.job_id,
    status: "completed",
    timestamp: new Date().toISOString(),
    phase_id: "-",
    agent_id: "-",
    task_id: "-",
    total_cost: totalCost,
    base64_img_string: finalRender.img,
    base64_img_string_mime: finalRender.mime || "image/png",
    session_events: events,
    events: [runSettingsEvent],       // into the doc's working transcript too
    user_message: ss.user_message ?? null,
    archival_report: ss.archival_report ?? null,
    generation_successful: ss.generation_successful ?? null,
    latest_description: ss.latest_description ?? null,
    original_query: ss.original_query ?? null
};

// Fire the completion payload to the Cloud Run listener
if (config.enable_gui_logging === true && config.gui_webhook_url) {
    try {
        await this.helpers.httpRequest({
            method: 'POST',
            url: config.gui_webhook_url,
            headers: { 'Content-Type': 'application/json' },
            body: finalPayload,
            json: true,
            timeout: 30000   // heaviest POST of the run: final image + full transcript,
                             // and the listener materializes session_events.json
                             // before responding
        });
    } catch (e) {
        throw new Error(`Final broadcast failed — completion NOT persisted: ${e.message}`);
    }
}

return [{ json: {
    status: "Workflow Complete",
    job_id: config.job_id,
    generation_successful: ss.generation_successful ?? null,
    user_message: ss.user_message ?? null,
    latest_description: ss.latest_description ?? null,
    archival_report: ss.archival_report ?? null,
    total_cost: totalCost,
    session_events: events
} }];

const input = items[0].json;

const taskMap = {
  "sales": "tsk_sales_001",
  "support": "tsk_support_042",
  "billing": "tsk_billing_007",
  "onboarding": "tsk_onboard_019"
};

return [{
  json: {
    ...input,
    PHASE_ID: "", // Set target Phase ID here
    AGENT_ID: "", // Set target Agent ID here
    TASK_ID: taskMap[input.enum_var] || input.enum_var
  }
}];

const input = items[0].json;

const taskMap = {
  "sales": "tsk_sales_001",
  "support": "tsk_support_042",
  "billing": "tsk_billing_007",
  "onboarding": "tsk_onboard_019"
};

return [{
  json: {
    ...input,
    PHASE_ID: "", // Set target Phase ID here
    AGENT_ID: "", // Set target Agent ID here
    TASK_ID: taskMap[input.enum_var] || input.enum_var
  }
}];

const input = items[0].json;

let nextTask = "";

switch (true) {
    // Condition 1: Multiple variables evaluated together
    case (input.needs_3d_planning === true && input.needs_arrangement_planning === true):
        nextTask = "inject_both";
        break;

    // Condition 2: Checking a completely different variable or property
    case (input.selected_workflow === "STANDARD_DIAGRAM"):
        nextTask = "standard_setup";
        break;

    // Condition 3: Evaluating length, math, or other logic
    case (input.history && input.history.length > 5):
        nextTask = "deep_history_review";
        break;

    // Fallback if none of the complex conditions are met
    default:
        nextTask = "default_fallback_task"; 
        break;
}

return [{
    json: {
        ...input,
        PHASE_ID: "", // Set target Phase ID here
        AGENT_ID: "", // Set target Agent ID here
        TASK_ID: nextTask
    }
}];

const input = items[0].json;
const state = input.session_state || {};
const lib = input.config.directive_library || {};

// Compose every directive whose planner flag is true in session_state.
// Adding a new constraint type = new schema boolean + new directive_library entry.
const directives = Object.entries(lib)
    .filter(([flag]) => state[flag] === true)
    .map(([, text]) => text);

// inject_constraints is the UNCONDITIONAL stage-3 briefing, and situational_directives
// carries its own leading newlines + header so it concatenates flush onto the end of
// problem_briefing (same idiom as retry_directives in plan_logic). No flags set => "",
// which contributes nothing to the briefing. The field must ALWAYS be present, though:
// the task's result templates {situational_directives}, and Node 1 throws a TEMPLATE
// ERROR on undefined ("" is fine).
return [{
    json: {
        ...input,
        PHASE_ID: "3",
        AGENT_ID: "scaffolding_manager",
        TASK_ID: "inject_constraints",
        situational_directives: directives.length
            ? "\n\n[SITUATIONAL DIRECTIVES]:\n" + directives.join("\n\n")
            : ""
    }
}];

// === 🐛 CFG INJECT EXECUTION ERROR ===
const inputData = items[0].json;

// 1. Extract the specific error
let errorText = "Unknown Error";
if (inputData.error) {
    if (inputData.error.message) {
        errorText = inputData.error.message;
    } else if (inputData.error.response && inputData.error.response.data) {
        const rawData = inputData.error.response.data;
        errorText = typeof rawData === 'object' ? JSON.stringify(rawData) : rawData.toString();
    } else if (inputData.error.description) { errorText = inputData.error.description; }
}

// 2. Format the Multiline Context
const formattedError = `While attempting to execute python code:
*** PYTHON RUNTIME ERROR ***
The code crashed with this error:
${errorText}`;

// 3. Clean Payload (Remove raw error object)
const cleanData = { ...inputData };
delete cleanData.error; 

// 4. Set routing for the Global Error Injector
return [{
    json: {
        ...cleanData,
        PHASE_ID: "3",
        AGENT_ID: "review_manager",
        TASK_ID: "log_error",
        error_text: formattedError // The UA will swap this into $error_text
    }
}];

// =====================================================================
//  QUERY LIBRARY + PAYLOAD BUILDER
//
//  Pick a query by setting "query_index" in the "Select Query" node.
//  Indexes are 1-based and match the // n comments below.
//
//  To add a query: append another backtick-quoted string to QUERIES.
//  Multi-line text needs no \n escaping inside backticks.
// =====================================================================

const QUERIES = [

// 1
`Problem: A cereal box says that now it contains 20% more. Originally, it came with 18.5 ounces of cereal. How much cereal does the box come with now?

Illustration: rectangular prism cereal box with top 1/6 shaded`,

// 2
`Problem: A scientist is studying the genes that determine the color of a mouse’s fur. When two mice with brown fur breed, there is a 25% chance that each baby will have white fur. For the experiment to continue, the scientist needs at least 2 out of 5 baby mice to have white fur. To simulate this situation, a coin can be flipped twice for each baby mouse. If the coin lands heads up both times, it represents a mouse with white fur.
Any other result represents a mouse with brown fur.

Illustration: 6 brown and 2 white mice`,

// 3
`Problem: For example, here is a scale drawing of a park where the scale is 1 cm to 90 m. The rectangle is 10 cm by 4 cm, so the actual dimensions of the park are 900 m by 360 m.

Illustration: rectangle park with 10:4 side ratio`,

// 4
`Problem: Sliced orange: 20 centimeters

Illustration: Half or a spherical orange [if possible: with a tape measure wrapped around it reading 20 cm for its circumference]`,

// 5
`Problem: Suppose we have two bags. One contains 1 star block and 4 moon blocks. The other contains 3 star blocks and 1 moon block.
If we select 1 block at random from each, what is the probability that we will get 2 star blocks or 2 moon blocks? To answer this question, we can draw a tree diagram to see all of the possible outcomes.

Illustration: One bag with 4 moon blocks and 1 star block, one bag with 3 star blocks and one moon block`,

// 6
`Problem: The field inside a running track is made up of a rectangle that is 84.39 m long and 73 m wide, together with a half circle at each end.

Illustration: a rectangle that is 84.39 m long and 73 m wide, together with a half circle at each end. There is then a track drawn around it that is 9.76m wide.`,

// 7
`Problem: What temperature is shown on each thermometer?

Illustration: A vertical Celsius thermometer ranging from -5 to 10, that shows 4 degrees as its reading`,

// 8
`Problem: Here is a scale drawing of an average seventh-grade student’s foot next to a scale drawing of a foot belonging to the person with the largest feet in the world. Estimate the length of the larger foot.

Illustration: Two images of feet that are approximately in a 2:3 ratio in terms of their lengths`,

// 9
`Problem: Which three spinners go together? Why do they go together?

Illustration: A circular spinner with 1/4 shaded green, 1/12 shaded blue, 1/10 shaded red, 17/30 shaded yellow.`,

// 10
`Problem: Estimate the length of each pencil.

Illustration: A ruler that goes from 0 to 20 cm. On top, there is a pencil measuring 5.5 cm. and on bottom, there is a pencil measuring 18 cm.`,

// 11
`Problem: Fluffy the poodle has arthritis and can't jump. A 5 foot long dog ramp leads up to a 3 foot high bed. How many feet is the base of the ramp from the foot of the bed?

Illustration: Draw the scene I've described, and a right-angled triangle illustrating the relationship between the dog ramp, the height of the bed, and the distance of the ramp's base from the bed. The hypotenuse represents the ramp, one vertical leg represents the height of the bed, and the horizontal leg represents the distance from the base of the ramp to the foot of the bed.`,

// 12 problem only
`Fluffy the poodle has arthritis and can't jump. A 5 foot long dog ramp leads up to a 3 foot high bed. How many feet is the base of the ramp from the foot of the bed?`,

// 13 diagram request only
`Fluffy the poodle has arthritis and can't jump. A 5 foot long dog ramp leads up to a 3 foot high bed. Draw the scene I've described, and a right-angled triangle illustrating the relationship between the dog ramp, the height of the bed, and the distance of the ramp's base from the bed. The hypotenuse represents the ramp, one vertical leg represents the height of the bed, and the horizontal leg represents the distance from the base of the ramp to the foot of the bed.`,

// 14 neither
`The prize, which will be announced in October, is one of six Nobel awards handed out by five Swedish academic bodies and a Norwegian committee.`,

// 15 simple image request
`I don't really have a math problem for you as such; jut make me a nice image of a cubic orange please`,

];

// ---------------------------------------------------------------------
//  Nothing to edit below this line.
// ---------------------------------------------------------------------

// Latest run of a node, by name. A bare $('Node').first() picks the ITEM, not the
// RUN — with no runIndex n8n resolves the run against THIS node's run index, so if
// "Select Query" ever lands inside a loop we'd silently read run 0 forever.
const latestRun = (nodeName) => {
    let latest = null;
    for (let run = 0; run < 50; run++) {
        let data;
        try { data = $(nodeName).all(0, run); }
        catch (e) { break; }
        if (data && data.length) latest = data[data.length - 1].json;
    }
    return latest;
};

const sel = latestRun('Select Query');
if (!sel) throw new Error('Select Query produced no data.');

const uuid = () =>
  (typeof crypto !== 'undefined' && crypto.randomUUID)
    ? crypto.randomUUID()
    : 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
        const r = (Math.random() * 16) | 0;
        return (c === 'x' ? r : (r & 0x3) | 0x8).toString(16);
      });

const raw = String(sel.query_index ?? '').trim();
const n = raw === '' ? 1 : Number(raw);

if (!Number.isInteger(n) || n < 1 || n > QUERIES.length) {
  throw new Error(
    `query_index must be a whole number from 1 to ${QUERIES.length}, got "${raw}".\n` +
    QUERIES.map((q, i) => `${i + 1}. ${q.split('\n')[0].slice(0, 70)}`).join('\n')
  );
}

const jobId = String(sel.job_id ?? '').trim() || uuid();
const style = String(sel.style_preference ?? '').trim() || 'casual_mobile';

console.log(`Query ${n}/${QUERIES.length} | job_id=${jobId}\n${QUERIES[n - 1].split('\n')[0]}`);

return [{
  json: {
    original_query: QUERIES[n - 1],
    job_id: jobId,
    style_preference: style,
  },
}];

// =============================================================================
// 🗄️ ARCHIVE SCAFFOLDING — pins the approved base diagram into the job bucket.
//
// Sits on both inbound edges of "Phase 3 - Output". This is the first point where
// the scaffold is final: on the standard path the LAST run of "Prepare for Vision"
// is the inspection-approved render; on DIRECT_IMAGE_GEN that node never ran.
//
// EXISTENCE, NOT ROUTE: session_state.selected_workflow is deliberately ignored. If
// an image is there we archive it; if it isn't — for ANY reason, including an
// upstream skip or crash — we ask the listener for the stock filler instead. So
// {job_id}/scaffolding.png always exists, and no consumer needs a missing-file case.
//
// ⚠️ NO IMAGE ENTERS OR LEAVES THIS NODE'S ITEM. The base64 lives in a local const
//    for the duration of the POST and dies with the node. The filler never touches
//    n8n at all — the listener does a server-side bucket-to-bucket copy. The
//    returned item is exactly { config, session_state, session_events }, which also
//    strips the base64_img_string that cfg22/23/24 rode in on.
// ⚠️ NEVER reach back by name with a bare .first()/.last()/.all(): those pick the
//    ITEM, not the RUN, and omitting runIndex makes n8n resolve against THIS node's
//    run index — on the phase-3 retry loop that's the FIRST, REJECTED scaffold.
// ⚠️ Requires /update-state to accept scaffolding at any status and to understand
//    `scaffolding_placeholder` (ritel-state-manager/main.py).
// =============================================================================

const latestRun = (nodeName) => {
    let latest = null;
    for (let run = 0; run < 50; run++) {   // cap is a sanity guard; real loops max at 3
        let data;
        try { data = $(nodeName).all(0, run); }
        catch (e) { break; }               // past the last run, or node never executed
        if (data && data.length) latest = data[data.length - 1].json;
    }
    return latest;                         // null = node never ran on this path
};

// $input, not a by-name reach-back: two different nodes feed this one, and what we
// pass through is our own input either way.
const { config, session_state, session_events } = items[0].json;
if (config === undefined || session_state === undefined || session_events === undefined) {
  throw new Error("Missing required payload properties: config, session_state, or session_events");
}

// Local scope only — never assigned onto the returned item.
const scaffold = latestRun('Prepare for Vision');
const img  = scaffold && scaffold.base64_img_string;
const mime = (scaffold && scaffold.base64_img_string_mime) || "image/png";

if (config.enable_gui_logging === true && config.gui_webhook_url && config.job_id) {
    try {
        await this.helpers.httpRequest({
            method: 'POST',
            url: config.gui_webhook_url,
            headers: { 'Content-Type': 'application/json' },
            body: img
                ? { job_id: config.job_id, status: "running",
                    scaffolding_base64_img_string: img,
                    scaffolding_base64_img_string_mime: mime }
                : { job_id: config.job_id, status: "running",
                    scaffolding_placeholder: true },
            json: true,
            timeout: 10000   // a real upload, not a progress ping — give it room
        });
    } catch (e) {
        console.error("Scaffolding archive failed:", e.message);  // non-fatal
    }
}

return [{ json: { config, session_state, session_events } }];

// =============================================================================
// 🙋 HUMAN GATE: ANNOUNCE  (Code node, "Run Once for All Items")
//
// Publishes the scaffolding-review gate to the job doc (status "awaiting_human" +
// a `human_review` block the frontend renders) and hands the following Wait node
// its time limit. No image rides along: the human is looking at {job_id}/latest.png,
// which "Prepare for Vision" already broadcast when it rendered this very scaffold.
// ⚠️ That broadcast is therefore LOAD-BEARING for the review — see the note on its
//    timeout in main_workflow_nodes/README.md §5.
// Sits in front of "Human Gate: Wait"; three edges feed it:
//   • "Human review?" / "Human available?"  — fresh gate after the machine verdict
//   • "Human decision" [corrections]         — the human clicked Give corrections
//                                              without typing anything yet
//   • "Manager understood?" [false]          — the manager asked a question; wait
//                                              for the human's answer
//
// STAGE   gate          the human may continue / give corrections / give up
//         conversation  a message round with the QA Inspection Manager
// REASON  review        the inspectors PASSED the scaffold (normal gate)
//         max_retries   the inspectors gave up on it; the human is the rescue
// WAIT    gate+review in "timeout" mode → config.human_review_timeouts.gate_seconds
//         everything else                → absent_minutes × 60 ("human walked away")
//
// The listener must be told about the gate, or waiting is pointless — but a dead
// listener must not hang the run for ten minutes either, so on a failed POST the
// wait collapses to one second and "Human Gate: Resolve" sees an ordinary timeout.
//
// ⚠️ $execution.resumeUrl is the ONE-SHOT resume URL of the Wait node that follows.
//    The frontend never calls it directly: ritel-state-manager /human-decision does.
// ⚠️ NEVER reach back by name with a bare .first()/.last()/.all() — see the
//    latestRun() note in "Archive Scaffolding". Same helper, same reason.
// =============================================================================

const latestRun = (nodeName) => {
    let latest = null;
    for (let run = 0; run < 50; run++) {
        let data;
        try { data = $(nodeName).all(0, run); }
        catch (e) { break; }
        if (data && data.length) latest = data[data.length - 1].json;
    }
    return latest;
};

const input = items[0].json;
const { config, session_state, session_events } = input;
if (!config || !session_state || !session_events) {
    throw new Error("Human Gate: Announce — missing config / session_state / session_events on the incoming item");
}

const mode = config.human_review_mode || "automatic";
const timeouts = config.human_review_timeouts || { gate_seconds: 30, absent_minutes: 10 };

// Rounds so far = manager replies in the human_review conversation (no counter state).
const round = session_events.filter(e => e.author === "inspection_manager" && String(e.task || "").startsWith("human_review")).length;

// Stage: explicit from "Human Gate: Resolve" (corrections click), else inferred —
// straight after a human_review reply we are mid-conversation; otherwise it's a gate.
const lastEvent = session_events[session_events.length - 1] || {};
const midConversation = lastEvent.author === "inspection_manager" && String(lastEvent.task || "").startsWith("human_review");
const stage = input.human_stage || (midConversation ? "conversation" : "gate");

// Reason: on a fresh gate the machine verdict decides; inside a conversation keep
// whatever the gate was opened with.
const reason = input.human_reason
    || (stage === "gate" ? (session_state.passed_inspection === true ? "review" : "max_retries")
                         : ((latestRun("Human Gate: Announce") || {}).human_reason || "review"));

const graceSeconds = (Number(timeouts.absent_minutes) || 10) * 60;

// SLICE, not the whole budget. A Wait node's time limit is fixed when it starts, so a
// running wait can never be extended. Instead each wait covers one slice; when it
// lapses, "Human Gate: Resolve" checks the deadline that /human-activity keeps pushing
// out and sends us round again if the human is demonstrably still there. So the opening
// 30s of "timeout" mode is 30s OF SILENCE, and every other wait is "N minutes since the
// last sign of life" rather than N minutes flat.
let waitSeconds = (stage === "gate" && reason === "review" && mode === "timeout")
    ? Number(timeouts.gate_seconds) || 30
    : graceSeconds;

// Re-announce after activity: serve out what is left of the extended deadline instead
// of starting a fresh full slice.
if (input.human_extend_seconds) {
    waitSeconds = Math.max(15, Math.min(graceSeconds, Math.round(Number(input.human_extend_seconds))));
}

const now = new Date();
// opened_at survives extensions: the frontend keys its gate widgets on it, so a moving
// deadline must NOT change it — re-keying would discard whatever the human has typed
// so far, at precisely the moment they are typing it.
const openedAt = input.human_opened_at || now.toISOString();
const humanReview = {
    stage,
    reason,
    mode,
    resume_url: $execution.resumeUrl,          // fresh every slice; the listener reads it live
    deadline: new Date(now.getTime() + waitSeconds * 1000).toISOString(),
    wait_seconds: waitSeconds,
    active_grace_seconds: graceSeconds,        // /human-activity extends to now + this
    last_activity: input.human_last_activity ?? null,
    round,
    last_reply: session_state.reply_to_human ?? null,
    understanding_confirmed: session_state.understanding_confirmed === true,
    opened_at: openedAt
};

if (config.enable_gui_logging === true && config.gui_webhook_url) {
    try {
        await this.helpers.httpRequest({
            method: "POST",
            url: config.gui_webhook_url,
            headers: { "Content-Type": "application/json" },
            body: {
                job_id: config.job_id,
                status: "awaiting_human",
                timestamp: now.toISOString(),
                phase_id: "3",
                agent_id: "inspection_manager",
                task_id: stage === "gate" ? "human_review_gate" : "human_review_conversation",
                human_review: humanReview
                // NO image: "Prepare for Vision" already broadcast this very render, so
                // {job_id}/latest.png is current and the frontend is already showing it.
                // Re-sending the base64 would just be a second full-size copy per gate.
            },
            json: true,
            timeout: 15000
        });
    } catch (e) {
        console.error("Human gate could not be announced — skipping the wait:", e.message);
        waitSeconds = 1;
    }
}

return [{ json: {
    config, session_state, session_events,
    human_stage: stage,
    human_reason: reason,
    human_round: round,
    human_wait_seconds: waitSeconds,   // ← "Human Gate: Wait" reads this: {{ $json.human_wait_seconds }}
    human_deadline: humanReview.deadline,
    human_opened_at: openedAt          // carried through extensions, for the widget keys
} }];

// =============================================================================
// 🙋 HUMAN GATE: RESOLVE  (Code node, "Run Once for All Items")
//
// Runs right after "Human Gate: Wait" and normalizes the two ways a Wait node can
// resume into ONE item for the "Human decision" Switch:
//   • resumed by webhook  → items[0].json is the request ({headers, params, query,
//                           body}); body = what ritel-state-manager /human-decision
//                           forwarded: { action, message, job_id, decided_at, ... }
//   • time limit reached  → items[0].json is our own Announce item passed through
//                           (no `body`) — the human did not answer
//
// Output (top-level, for the Switch and the cfg nodes downstream):
//   human_action   continue | message | corrections | rework | fail | abort
//   human_message  the human's text (message rounds)
//   human_stage / human_reason / human_round  — echoed from Announce
//   human_decision_text — the note log_human_decision writes into history
//
// DECISION TABLE (stage / reason / what came back → action)
//   gate         continue            → continue   (accept as drawn; on max_retries: accept anyway)
//   gate         corrections (empty) → corrections (open the conversation, wait for text)
//   gate/conv    corrections + text  → message
//   conv         message             → message
//   any          abort               → abort
//   gate review  timeout             → continue   (the "30 s then automatic" mode, or absent human)
//   gate max_r.  timeout             → fail       (nobody rescued it — same outcome as no human)
//   conv         continue / timeout  → rework if the manager already holds corrections
//                                      (round ≥ 1 and scaffold not marked acceptable),
//                                      else continue / fail exactly as the gate would
// =============================================================================

const latestRun = (nodeName) => {
    let latest = null;
    for (let run = 0; run < 50; run++) {
        let data;
        try { data = $(nodeName).all(0, run); }
        catch (e) { break; }
        if (data && data.length) latest = data[data.length - 1].json;
    }
    return latest;
};

const announced = latestRun("Human Gate: Announce");
if (!announced) throw new Error("Human Gate: Resolve — no output from 'Human Gate: Announce' found");
const { config, session_state, session_events, human_stage: stage, human_reason: reason,
        human_round: round, human_wait_seconds: waitSeconds, human_opened_at: openedAt } = announced;

const incoming = items[0].json || {};
const body = incoming.body && typeof incoming.body === "object" ? incoming.body : null;
let action = body && body.action ? String(body.action).toLowerCase() : "timeout";
const message = body && body.message ? String(body.message).trim() : "";
if (action === "corrections" && message) action = "message";
const timedOut = action === "timeout";

// === ⏱️ STILL THERE? ===
// The slice lapsed. /human-activity has been pushing the gate's deadline out on every
// keystroke, so a deadline still in the future means the human is mid-thought: open
// another slice rather than deciding for them. Only asked on the timeout branch, and
// only when a human could plausibly be present.
let extendSeconds = 0;
let lastActivity = null;
if (timedOut && (config.human_review_mode || "automatic") !== "automatic") {
    try {
        const summary = await this.helpers.httpRequest({
            method: "GET",
            url: `${config.gui_webhook_url.replace(/\/update-state$/, "")}/summary/${config.job_id}`,
            json: true,
            timeout: 10000
        });
        const gate = summary?.human_review || {};
        lastActivity = gate.last_activity ?? null;
        const remaining = (new Date(gate.deadline).getTime() - Date.now()) / 1000;
        if (gate.last_activity && Number.isFinite(remaining) && remaining > 5) {
            extendSeconds = remaining;
        }
    } catch (e) {
        // Unreachable listener: fall through and time out normally. Waiting longer on
        // the strength of a lookup we could not perform would be the wrong default.
        console.error("Activity check failed, treating the wait as expired:", e.message);
    }
}

if (extendSeconds) {
    return [{ json: {
        config, session_state, session_events,
        human_action: "extend",
        human_stage: stage,
        human_reason: reason,
        human_round: round,
        human_opened_at: openedAt,
        human_last_activity: lastActivity,
        human_extend_seconds: extendSeconds
    } }];
}

const heldCorrections = round > 0 && session_state.scaffold_acceptable_as_is !== true;
const minutes = Math.round((waitSeconds || 0) / 60);
const failedTimes = (session_state.inspection_retry_count || (announced.session_state || {}).inspection_retry_count || 3);

let outcome, note = "";
switch (action) {
    case "message":
    case "corrections":
        outcome = action;                       // no history note: the conversation IS the record
        break;
    case "abort":
        outcome = "abort";
        note = "The human reviewer chose to stop the run at the scaffolding review.";
        break;
    default: {                                  // continue | timeout
        if (stage === "conversation" && heldCorrections) {
            outcome = "rework";
            note = timedOut
                ? `The human reviewer gave corrections but stopped answering (${minutes} min); proceeding with the corrections gathered so far. Retry counters reset.`
                : `The human reviewer gave corrections and asked us to proceed. The QA Inspection Manager's fix_instructions carry them. Retry counters reset.`;
        } else if (reason === "max_retries" && timedOut) {
            outcome = "fail";
            note = `The scaffolding failed inspection repeatedly and the human reviewer did not respond within ${minutes} min.`;
        } else if (reason === "max_retries") {
            outcome = "continue";
            note = "The scaffolding failed inspection repeatedly; the human reviewer chose to accept it as it is and continue.";
        } else if (timedOut) {
            outcome = "continue";
            note = `The human reviewer was offered a review of the approved scaffolding and did not respond within ${waitSeconds}s; proceeding automatically.`;
        } else {
            outcome = "continue";
            note = "The human reviewer looked at the approved scaffolding and accepted it as drawn.";
        }
    }
}

return [{ json: {
    config, session_state, session_events,
    human_action: outcome,
    human_message: message,
    human_stage: outcome === "corrections" ? "conversation" : stage,   // corrections click → Announce opens the conversation
    human_reason: reason,
    human_round: round,
    // A corrections click reopens the SAME gate as a conversation, so the frontend's
    // widgets should survive the transition; a decision that ends the gate does not care.
    human_opened_at: outcome === "corrections" ? openedAt : null,
    human_decision_text: note
} }];

// =============================================================================
// 🙋 HUMAN OUTCOME  (Code node, "Run Once for All Items")
//
// Funnel for every way the human review can END. Two kinds of item arrive:
//   • from "Human decision" (continue | rework | fail | abort): the Resolve item,
//     which already carries human_action + human_decision_text — passed through.
//   • from "Manager understood?" [true]: the Universal Agent's output after a
//     human_review_* turn. The manager's verdict decides:
//         user_wants_to_stop        → abort
//         scaffold_acceptable_as_is → continue      else → rework
//
// The human has ONE box and ONE button, so there is no approve/reject/cancel control
// to read: the manager infers the intent from what they wrote and expresses it in
// these flags. That is why abort can arrive from here rather than only from a click.
//
// Everything then goes: → cfg log human decision → human_gate - log_human_decision
// → "After human log" (Switch on $('Human outcome').item.json.human_action), which
// reads THIS node's output because the Universal Agent call in between returns only
// { config, session_state, session_events } and drops top-level fields.
// =============================================================================

const input = items[0].json;
const { config, session_state, session_events } = input;
if (!config || !session_state || !session_events) {
    throw new Error("Human outcome — missing config / session_state / session_events on the incoming item");
}

let action = input.human_action;
let note = input.human_decision_text || "";

if (!action) {
    const round = session_events.filter(e => e.author === "inspection_manager" && String(e.task || "").startsWith("human_review")).length;
    // Order matters: stopping is checked first, because a human who asked to stop has
    // overridden every other reading of what they wrote.
    if (session_state.user_wants_to_stop === true) {
        action = "abort";
        note = `The human reviewer asked to stop the run at the scaffolding review, after ${round} exchange(s). The QA Inspection Manager read that as a request to abandon rather than to correct.`;
    } else if (session_state.scaffold_acceptable_as_is === true) {
        action = "continue";
        note = `After ${round} exchange(s) the human reviewer confirmed the scaffolding is fine as drawn.`;
    } else {
        action = "rework";
        note = `The human reviewer gave corrections (${round} exchange(s)); the QA Inspection Manager confirmed it understands them and relayed them as fix_instructions. Retry counters reset; redrawing the scaffolding.`;
    }
}

return [{ json: {
    config, session_state, session_events,
    human_action: action,                 // continue | rework | fail | abort
    human_decision_text: note,            // templated by log_human_decision ({human_decision_text})
    human_round: input.human_round ?? null
} }];

// =============================================================================
// 🙋 FINAL GATE: ANNOUNCE  (Code node, "Run Once for All Items")
//
// The final-illustration twin of "Human Gate: Announce". Publishes the review gate to
// the job doc (status "awaiting_human" + a `human_review` block the frontend renders)
// and hands "Final Gate: Wait" its time limit. Three edges feed it:
//   • "Final review?" / "Final available?"  — fresh gate after the Gatekeeper's verdict
//   • "Final decision" [corrections]         — kept for parity; the one-button UI never
//                                              sends it, so this edge never fires
//   • "Final understood?" [false]            — the Gatekeeper asked a question; wait
//                                              for the human's answer
//
// No image rides along: node 3 of "artist - render_final" already broadcast this very
// illustration, so {job_id}/latest.png is current and the frontend is showing it.
//
// ⚠️ EVERY name and flag this gate depends on is in GATE below. The scaffold version
//    hard-codes "Human Gate: Announce", "inspection_manager" and "human_review" — a
//    pasted copy left unedited would reach back into the SCAFFOLD gate and read its data
//    without any error to warn you. Node names here must match your canvas exactly.
// ⚠️ NEVER reach back by name with a bare .first()/.last()/.all() — see the
//    latestRun() note in "Archive Scaffolding". Same helper, same reason.
// =============================================================================

const GATE = {
    gate: "final",                          // tells the frontend which wording to show
    announceNode: "Final Gate: Announce",   // THIS node's own name, for the reach-back
    manager: "issue_aggregator",            // who holds the conversation
    taskPrefix: "final_review",             // final_review_open / final_review_reply
    passedFlag: "final_pass",               // the Gatekeeper's verdict: review vs max_retries
    phase: "5",
};

const latestRun = (nodeName) => {
    let latest = null;
    for (let run = 0; run < 50; run++) {
        let data;
        try { data = $(nodeName).all(0, run); }
        catch (e) { break; }
        if (data && data.length) latest = data[data.length - 1].json;
    }
    return latest;
};

const input = items[0].json;
const { config, session_state, session_events } = input;
if (!config || !session_state || !session_events) {
    throw new Error(`${GATE.announceNode} — missing config / session_state / session_events on the incoming item`);
}

const mode = config.human_review_mode || "automatic";
const timeouts = config.human_review_timeouts || { gate_seconds: 30, absent_minutes: 10 };

const isGateTurn = e => e.author === GATE.manager && String(e.task || "").startsWith(GATE.taskPrefix);

// Rounds so far = this gate's manager replies (no counter state).
const round = session_events.filter(isGateTurn).length;

// Stage: explicit from "Final Gate: Resolve", else inferred — straight after one of
// this gate's replies we are mid-conversation; otherwise it's a fresh gate.
const lastEvent = session_events[session_events.length - 1] || {};
const midConversation = isGateTurn(lastEvent);
const stage = input.human_stage || (midConversation ? "conversation" : "gate");

// Reason: on a fresh gate the verdict decides; inside a conversation keep whatever the
// gate was opened with.
const reason = input.human_reason
    || (stage === "gate" ? (session_state[GATE.passedFlag] === true ? "review" : "max_retries")
                         : ((latestRun(GATE.announceNode) || {}).human_reason || "review"));

const graceSeconds = (Number(timeouts.absent_minutes) || 10) * 60;

// SLICE, not the whole budget — see "Human Gate: Announce". The opening window in
// "timeout" mode is gate_seconds OF SILENCE; typing extends it via /human-activity.
let waitSeconds = (stage === "gate" && reason === "review" && mode === "timeout")
    ? Number(timeouts.gate_seconds) || 30
    : graceSeconds;

if (input.human_extend_seconds) {
    waitSeconds = Math.max(15, Math.min(graceSeconds, Math.round(Number(input.human_extend_seconds))));
}

const now = new Date();
// opened_at survives extensions: the frontend keys its gate widgets on it.
const openedAt = input.human_opened_at || now.toISOString();
const humanReview = {
    gate: GATE.gate,
    stage,
    reason,
    mode,
    resume_url: $execution.resumeUrl,          // fresh every slice; the listener reads it live
    deadline: new Date(now.getTime() + waitSeconds * 1000).toISOString(),
    wait_seconds: waitSeconds,
    active_grace_seconds: graceSeconds,        // /human-activity extends to now + this
    last_activity: input.human_last_activity ?? null,
    round,
    // Only mid-conversation. reply_to_human is shared state, and on a fresh gate it
    // still holds the SCAFFOLD manager's last words.
    last_reply: midConversation ? (session_state.reply_to_human ?? null) : null,
    understanding_confirmed: midConversation && session_state.understanding_confirmed === true,
    opened_at: openedAt
};

if (config.enable_gui_logging === true && config.gui_webhook_url) {
    try {
        await this.helpers.httpRequest({
            method: "POST",
            url: config.gui_webhook_url,
            headers: { "Content-Type": "application/json" },
            body: {
                job_id: config.job_id,
                status: "awaiting_human",
                timestamp: now.toISOString(),
                phase_id: GATE.phase,
                agent_id: GATE.manager,
                task_id: stage === "gate" ? `${GATE.taskPrefix}_gate` : `${GATE.taskPrefix}_conversation`,
                human_review: humanReview
            },
            json: true,
            timeout: 15000
        });
    } catch (e) {
        console.error(`${GATE.announceNode}: gate could not be announced — skipping the wait:`, e.message);
        waitSeconds = 1;
    }
}

return [{ json: {
    config, session_state, session_events,
    human_stage: stage,
    human_reason: reason,
    human_round: round,
    human_wait_seconds: waitSeconds,   // ← "Final Gate: Wait" reads this: {{ $json.human_wait_seconds }}
    human_deadline: humanReview.deadline,
    human_opened_at: openedAt
} }];

// =============================================================================
// 🙋 FINAL GATE: RESOLVE  (Code node, "Run Once for All Items")
//
// The final-illustration twin of "Human Gate: Resolve". Runs right after "Final Gate:
// Wait" and turns the two ways a Wait node can resume — a webhook call, or its time
// limit — into ONE item for the "Final decision" Switch.
//
// Output: human_action ∈ continue | message | extend | rework | fail | abort, plus
// human_message, human_decision_text and the echoed stage / reason / round.
//
//   gate         continue            → continue   (release as painted; max_retries: accept anyway)
//   gate/conv    message             → message
//   gate review  timeout             → continue   (the "30 s then automatic" mode, or absent human)
//   gate max_r.  timeout             → fail       (nobody rescued it — same outcome as no human)
//   conv         continue / timeout  → rework if the Gatekeeper already holds corrections,
//                                      else continue / fail exactly as the gate would
//   any          lapsed but active   → extend     (see STILL THERE?)
//
// ⚠️ Every name and flag is in GATE. An unedited copy of the scaffold version would
//    read "Human Gate: Announce" and scaffold_acceptable_as_is — the SCAFFOLD gate's
//    data — and nothing would fail loudly.
// =============================================================================

const GATE = {
    announceNode: "Final Gate: Announce",   // must match the canvas name exactly
    acceptableFlag: "image_acceptable_as_is",
    subject: "final illustration",
};

const latestRun = (nodeName) => {
    let latest = null;
    for (let run = 0; run < 50; run++) {
        let data;
        try { data = $(nodeName).all(0, run); }
        catch (e) { break; }
        if (data && data.length) latest = data[data.length - 1].json;
    }
    return latest;
};

const announced = latestRun(GATE.announceNode);
if (!announced) throw new Error(`Final Gate: Resolve — no output from '${GATE.announceNode}' found`);
const { config, session_state, session_events, human_stage: stage, human_reason: reason,
        human_round: round, human_wait_seconds: waitSeconds, human_opened_at: openedAt } = announced;

const incoming = items[0].json || {};
const body = incoming.body && typeof incoming.body === "object" ? incoming.body : null;
let action = body && body.action ? String(body.action).toLowerCase() : "timeout";
const message = body && body.message ? String(body.message).trim() : "";
if (action === "corrections" && message) action = "message";
const timedOut = action === "timeout";

// === ⏱️ STILL THERE? ===
// The slice lapsed. If /human-activity has pushed the deadline into the future, the
// human is mid-thought: open another slice rather than deciding for them.
let extendSeconds = 0;
let lastActivity = null;
if (timedOut && (config.human_review_mode || "automatic") !== "automatic") {
    try {
        const summary = await this.helpers.httpRequest({
            method: "GET",
            url: `${config.gui_webhook_url.replace(/\/update-state$/, "")}/summary/${config.job_id}`,
            json: true,
            timeout: 10000
        });
        const gate = summary?.human_review || {};
        lastActivity = gate.last_activity ?? null;
        const remaining = (new Date(gate.deadline).getTime() - Date.now()) / 1000;
        if (gate.last_activity && Number.isFinite(remaining) && remaining > 5) {
            extendSeconds = remaining;
        }
    } catch (e) {
        console.error("Activity check failed, treating the wait as expired:", e.message);
    }
}

if (extendSeconds) {
    return [{ json: {
        config, session_state, session_events,
        human_action: "extend",
        human_stage: stage,
        human_reason: reason,
        human_round: round,
        human_opened_at: openedAt,
        human_last_activity: lastActivity,
        human_extend_seconds: extendSeconds
    } }];
}

const heldCorrections = round > 0 && session_state[GATE.acceptableFlag] !== true;
const minutes = Math.round((waitSeconds || 0) / 60);

let outcome, note = "";
switch (action) {
    case "message":
    case "corrections":
        outcome = action;                       // no history note: the conversation IS the record
        break;
    case "abort":
        outcome = "abort";
        note = `The human reviewer chose to stop the run at the ${GATE.subject} review.`;
        break;
    default: {                                  // continue | timeout
        if (stage === "conversation" && heldCorrections) {
            outcome = "rework";
            note = timedOut
                ? `The human reviewer gave corrections to the ${GATE.subject} but stopped answering (${minutes} min); proceeding with the corrections gathered so far. Retry counters reset.`
                : `The human reviewer gave corrections to the ${GATE.subject} and asked us to proceed. The Final Gatekeeper's fix_instructions carry them. Retry counters reset.`;
        } else if (reason === "max_retries" && timedOut) {
            outcome = "fail";
            note = `The ${GATE.subject} failed review repeatedly and the human reviewer did not respond within ${minutes} min.`;
        } else if (reason === "max_retries") {
            outcome = "continue";
            note = `The ${GATE.subject} failed review repeatedly; the human reviewer chose to accept it as it is and release it.`;
        } else if (timedOut) {
            outcome = "continue";
            note = `The human reviewer was offered a review of the approved ${GATE.subject} and did not respond within ${waitSeconds}s; releasing it automatically.`;
        } else {
            outcome = "continue";
            note = `The human reviewer looked at the approved ${GATE.subject} and accepted it as painted.`;
        }
    }
}

return [{ json: {
    config, session_state, session_events,
    human_action: outcome,
    human_message: message,
    human_stage: outcome === "corrections" ? "conversation" : stage,
    human_reason: reason,
    human_round: round,
    human_opened_at: outcome === "corrections" ? openedAt : null,
    human_decision_text: note
} }];

// =============================================================================
// 🙋 FINAL OUTCOME  (Code node, "Run Once for All Items")
//
// The final-illustration twin of "Human outcome": the funnel for every way the final
// review can END. Two kinds of item arrive:
//   • from "Final decision" (continue | rework | fail | abort): the Resolve item, which
//     already carries human_action + human_decision_text — passed through.
//   • from "Final understood?" [true]: the Universal Agent's output after a
//     final_review_* turn. The Gatekeeper's verdict decides:
//         user_wants_to_stop      → abort
//         image_acceptable_as_is  → continue      else → rework
//
// Then: → cfg log final decision (AGENT_ID final_gate) → final_gate - log_final_decision →
// "After final log", which switches on $('Final outcome').item.json.human_action —
// THIS node's name. The Universal Agent call in between returns only
// { config, session_state, session_events } and drops top-level fields.
//
// ⚠️ Rename this node to exactly "Final outcome", and point "After final log" at it.
//    Left as a copy of "Human outcome", it would switch on the SCAFFOLD gate's result.
// =============================================================================

const GATE = {
    manager: "issue_aggregator",
    taskPrefix: "final_review",
    acceptableFlag: "image_acceptable_as_is",
    subject: "final illustration",
};

const input = items[0].json;
const { config, session_state, session_events } = input;
if (!config || !session_state || !session_events) {
    throw new Error("Final outcome — missing config / session_state / session_events on the incoming item");
}

let action = input.human_action;
let note = input.human_decision_text || "";

if (!action) {
    const round = session_events.filter(e => e.author === GATE.manager && String(e.task || "").startsWith(GATE.taskPrefix)).length;
    // Stopping first: a human who asked to stop has overridden every other reading.
    if (session_state.user_wants_to_stop === true) {
        action = "abort";
        note = `The human reviewer asked to stop the run at the ${GATE.subject} review, after ${round} exchange(s). The Final Gatekeeper read that as a request to abandon rather than to correct.`;
    } else if (session_state[GATE.acceptableFlag] === true) {
        action = "continue";
        note = `After ${round} exchange(s) the human reviewer confirmed the ${GATE.subject} is fine as painted.`;
    } else {
        action = "rework";
        note = `The human reviewer gave corrections to the ${GATE.subject} (${round} exchange(s)); the Final Gatekeeper confirmed it understands them and relayed them as fix_instructions. Retry counters reset; repainting.`;
    }
}

return [{ json: {
    config, session_state, session_events,
    human_action: action,                 // continue | rework | fail | abort
    human_decision_text: note,            // templated by log_human_decision ({human_decision_text})
    human_round: input.human_round ?? null
} }];

// =============================================================================
// 🔁 RESUME: LOAD JOB  (Code node, "Run Once for All Items")
//
// Entry point for "Resume final review": reopens a FINISHED job at the final
// illustration gate so the human can do another correction round with the Final
// Gatekeeper. Called by the frontend through the "Resume Trigger" webhook:
//
//   POST /webhook/resume-final-gate
//   { source_job_id, mode: "overwrite" | "new", target_job_id (new mode only),
//     max_text_tier, max_image_tier, style_preference (fallback only) }
//
// This node only gathers what Load Config needs to BUILD a config. The state rebuild,
// images and job-doc setup happen in "Resume: Rebuild State", after Load Config, because
// the replay needs config.tasks (hoisted fields, textResult keys).
//
// THE STYLE: Load Config bakes the chosen style into the instruction strings, so the
// style key has to be recovered.
//   1. Recorded: since 2026-11-04 every completed run ends with a "run_settings" event
//      (Send Final Broadcast, Resume: Restore Completed) holding config.style_preference.
//      The last one wins. Exact, and covers every style added later.
//   2. Inferred, for jobs that finished before that: the artist's logged prompts
//      (plan_finishing / render_final) quote the style description word for word, so a
//      distinctive phrase of each description identifies it. Those jobs can only have used
//      the five styles below, so STYLE_SIGNATURES never needs new entries.
//   3. Otherwise the frontend's style_preference.
//
// Refuses (throws, and the webhook answers with the error) when the source has no
// finished result to review, or when the source or target job is busy.
// =============================================================================

const STATE_MANAGER = "https://ritel-state-manager-194521282716.us-south1.run.app";
// "starting" is NOT busy: the frontend stamps it on the job just before calling this
// webhook, so its poll loop doesn't stop on the old "completed" status.
const BUSY = ["running", "awaiting_human"];
const STYLE_SIGNATURES = {
    storybook: "classic children's storybooks",
    casual_mobile: "casual mobile game art",
    cel_shaded_anime: "studio anime and cel-shaded",
    claymation_diorama: "physical diorama made of clay",
    mid_century_modern: "1950s and 1960s educational posters",
};

const body = items[0].json.body || {};
const mode = body.mode;
if (mode !== "overwrite" && mode !== "new") {
    throw new Error(`Resume: mode must be "overwrite" or "new" (got ${JSON.stringify(mode)})`);
}
const sourceId = String(body.source_job_id || "").trim();
const targetId = mode === "overwrite" ? sourceId : String(body.target_job_id || "").trim();
if (!sourceId) throw new Error("Resume: source_job_id is required");
if (!targetId) throw new Error('Resume: target_job_id is required in "new" mode');
if (mode === "new" && targetId === sourceId) throw new Error('Resume: "new" mode needs a different target_job_id');

const get = (path) => this.helpers.httpRequest({ method: "GET", url: `${STATE_MANAGER}${path}`, json: true, timeout: 30000 });

const summary = await get(`/summary/${sourceId}`);
const artifacts = summary.artifacts || {};
if (!artifacts["final_illustration.png"] || !artifacts["session_events.json"]) {
    throw new Error(`Resume: job ${sourceId} has no finished illustration to review (status: ${summary.status ?? "unknown"})`);
}
if (BUSY.includes(summary.status)) {
    throw new Error(`Resume: job ${sourceId} is ${summary.status}; wait for it to finish first`);
}
if (mode === "new") {
    // A brand-new target id normally doesn't exist yet: /summary answers 404, which is fine.
    // (Read the status directly: n8n's wrapped HTTP errors don't expose it reliably.)
    const res = await this.helpers.httpRequest({
        method: "GET", url: `${STATE_MANAGER}/summary/${targetId}`, json: true, timeout: 30000,
        returnFullResponse: true, ignoreHttpStatusErrors: true,
    });
    if (res.statusCode !== 404 && res.statusCode !== 200) {
        throw new Error(`Resume: could not check target job ${targetId} (HTTP ${res.statusCode})`);
    }
    const target = res.statusCode === 200 ? res.body || {} : {};
    if (BUSY.includes(target.status)) throw new Error(`Resume: target job ${targetId} is already ${target.status}`);
}

const transcript = (await get(`/transcript/${sourceId}`))
    .slice()
    .sort((a, b) => String(a.timestamp || "").localeCompare(String(b.timestamp || "")));

// Style, 1: the last run_settings record.
let recordedStyle = null;
const settingsEvent = [...transcript].reverse().find(e => e.author === "run_settings");
if (settingsEvent) {
    try { recordedStyle = JSON.parse(settingsEvent.parts[0].text).style_preference || null; }
    catch (e) { /* malformed record: fall through to inference */ }
}

// Style, 2: count each signature across the artist's logged prompts; the most frequent wins.
const artistPrompts = transcript
    .filter(e => e.author === "system" && ["plan_finishing", "render_final"].includes(e.task))
    .map(e => JSON.stringify(e.parts || []))
    .join(" ");
let inferredStyle = null, best = 0;
for (const [key, phrase] of Object.entries(STYLE_SIGNATURES)) {
    const hits = artistPrompts.split(phrase).length - 1;
    if (hits > best) { best = hits; inferredStyle = key; }
}
const style = recordedStyle || inferredStyle || body.style_preference || "casual_mobile";
const styleSource = recordedStyle ? "recorded" : inferredStyle ? "inferred" : body.style_preference ? "frontend" : "default";

// Items reaching Load Config: these top-level fields are exactly what it reads to build a
// config, plus session_events (passed through). `resume` and anything else is dropped by
// Load Config, so the images never ride along; Rebuild State reaches back to this node.
return [{ json: {
    job_id: targetId,
    original_query: summary.original_query ?? null,
    style_preference: style,
    max_text_tier: body.max_text_tier || "slow",
    max_image_tier: body.max_image_tier || "slow",
    human_review_mode: "wait",          // a resumed gate always waits for the human
    session_events: transcript,
    resume: {
        source_job_id: sourceId,
        target_job_id: targetId,
        mode,
        style_source: styleSource,      // recorded | inferred | frontend | default
        // Restored as-is if the human keeps the previous result (Resume: Restore Completed).
        previous: {
            user_message: summary.user_message ?? null,
            archival_report: summary.archival_report ?? null,
            latest_description: summary.latest_description ?? null,
            generation_successful: summary.generation_successful ?? null,
        },
    },
} }];

// =============================================================================
// 🔁 RESUME: REBUILD STATE  (Code node, "Run Once for All Items")
//
// Runs after "Load Resume Config", which built a fresh config (inferred style, current
// tiers, human_review_mode "wait") and seeded session_state with original_query and
// the empty directive slots. This node:
//
//   1. Rebuilds session_state by replaying the transcript: every agent turn whose text
//      is a JSON object is merged in order, exactly as Universal Agent node 3 did live,
//      minus the task's hoist_result_fields. Single-field textResult (no_model) turns
//      log only their value, so the key comes from config. Prompts, errors and images
//      add nothing. Variables that were only ever swept in from the top level (retry
//      counters, directives) are not recoverable, and the final-gate path does not need
//      them: Load Config seeded the directive slots and "Final corrections" re-arms them.
//   2. Fetches the scaffold and final illustration from the public job bucket.
//   3. Overwrite mode: asks the state manager to copy the job's current result into
//      {job_id}/previous/ first, and refuses to continue if it can't.
//   4. Sets up the target job doc through /update-state: status running, a
//      final_gate "resume_final_gate" marker event, the final illustration as latest.png
//      (what the gate shows). "new" mode also copies the transcript and the scaffold.
//   5. Hands Final Gate: Announce a fresh gate (stage gate, reason review).
//
// The scaffold and final image ride on THIS node's output (resume_* fields). Announce
// drops them; cfg25 / cfg26 and Resume: Restore Completed reach back here by name.
// ⚠️ Keep the name "Resume: Rebuild State": those three nodes reference it.
// =============================================================================

const BUCKET = "https://storage.googleapis.com/edee-job-archives-0925957935";
const load = $("Resume: Load Job").first().json;
const { source_job_id: sourceId, target_job_id: targetId, mode, style_source } = load.resume;
const { config, session_state: seeded, session_events: events } = items[0].json;
if (!config || !seeded || !Array.isArray(events)) {
    throw new Error("Resume: Rebuild State — missing config / session_state / session_events from Load Resume Config");
}
const stateManager = config.gui_webhook_url.replace(/\/update-state$/, "");

// === 1. Replay ===
const state = { ...seeded };
let applied = 0;
for (const ev of events) {
    // run_settings records launch choices for Load Job, not an agent's output.
    if (["system", "user", "run_settings"].includes(ev.author) || ev.status === "error") continue;
    const task = config.tasks[ev.task] || {};
    const text = (ev.parts || []).filter(p => typeof p.text === "string" && !p.thought).map(p => p.text).join("");
    if (!text) continue;
    let result = null;
    try { result = JSON.parse(text); } catch (e) { /* plain-text turn */ }
    if (result && typeof result === "object" && !Array.isArray(result)) {
        Object.assign(state, result);
    } else if (task.textResult && Object.keys(task.textResult).length === 1) {
        state[Object.keys(task.textResult)[0]] = text;
    } else {
        continue;
    }
    for (const k of task.hoist_result_fields || []) delete state[k];
    applied++;
}
if (!state.latest_description) {
    throw new Error(`Resume: could not rebuild latest_description from job ${sourceId}'s transcript (${applied} turns replayed)`);
}

// === 2. Images ===
const fetchImage = async (name) => {
    const res = await this.helpers.httpRequest({
        method: "GET", url: `${BUCKET}/${sourceId}/${name}`,
        encoding: "arraybuffer", returnFullResponse: true, timeout: 60000,
    });
    return { b64: Buffer.from(res.body).toString("base64"), mime: (res.headers["content-type"] || "image/png").split(";")[0] };
};
const finalImage = await fetchImage("final_illustration.png");
// DIRECT_IMAGE_GEN jobs have the stock placeholder in scaffolding.png: nothing to paint over.
const noScaffold = state.selected_workflow === "DIRECT_IMAGE_GEN";
const scaffold = noScaffold ? { b64: "", mime: "" } : await fetchImage("scaffolding.png");

// === 3. Back up the result we are about to overwrite ===
if (mode === "overwrite") {
    try {
        await this.helpers.httpRequest({ method: "POST", url: `${stateManager}/backup-round/${targetId}`, json: true, timeout: 60000 });
    } catch (e) {
        throw new Error(`Resume: could not back up job ${targetId} to previous/ (${e.message}); refusing to overwrite it. Is the state manager up to date?`);
    }
}

// === 4. Target job doc ===
const now = new Date();
const marker = {
    author: "final_gate",
    task: "resume_final_gate",
    status: "ok",
    parts: [{ text: mode === "overwrite"
        ? `The finished job was reopened at the final illustration review on ${now.toISOString().slice(0, 10)} for another correction round. The illustration under review is the one this job finished with.`
        : `This job continues job ${sourceId}, reopened at the final illustration review on ${now.toISOString().slice(0, 10)} for another correction round. The illustration under review is the one that job finished with.` }],
    timestamp: now.toISOString(),
    model: "none",
    cost: 0,
};
const sessionEvents = [...events, marker];

await this.helpers.httpRequest({
    method: "POST",
    url: config.gui_webhook_url,
    headers: { "Content-Type": "application/json" },
    json: true,
    timeout: 60000,
    body: {
        job_id: targetId,
        status: "running",
        timestamp: now.toISOString(),
        phase_id: "5",
        agent_id: "final_gate",
        task_id: "resume_final_gate",
        original_query: state.original_query ?? null,
        // "new": the whole history moves to the new job. "overwrite": the doc already has it.
        events: mode === "new" ? sessionEvents : [marker],
        base64_img_string: finalImage.b64,               // → {job_id}/latest.png + live_image
        base64_img_string_mime: finalImage.mime,
        ...(mode === "new"
            ? (noScaffold ? { scaffolding_placeholder: true }
                          : { scaffolding_base64_img_string: scaffold.b64, scaffolding_base64_img_string_mime: scaffold.mime })
            : {}),
        ...(mode === "new" ? { resumed_from: sourceId } : {}),
    },
});

// === 5. Into the final gate ===
return [{ json: {
    config,
    session_state: state,
    session_events: sessionEvents,
    human_stage: "gate",
    human_reason: "review",
    resume_scaffold_b64: scaffold.b64,
    resume_scaffold_mime: scaffold.mime,
    resume_final_b64: finalImage.b64,
    resume_final_mime: finalImage.mime,
    resume_note: `${applied} turns replayed; style ${load.style_preference} (${style_source})`,
} }];

// =============================================================================
// 🔁 RESUME: RESTORE COMPLETED  (Code node, "Run Once for All Items")
//
// Ends a resumed job WITHOUT re-running Phase 6, when the human's resumed round changed
// nothing that needs a new report. Reached from two IFs after "After final log", and from
// one after "After human log" (a stop at the scaffold gate during a redraw):
//   • continue, and the artist never ran in this execution: approved as is, walked away
//     (the gate timed out), or the Gatekeeper concluded no changes were wanted. The
//     report from the original run still describes this exact image, so re-generating it
//     would only spend tokens.
//   • abort: the human asked to stop the round. Stopping a resume means keeping what
//     the job had, even if a repaint already happened in this round.
//
// Marks the job completed with the illustration it was resumed with, its previous
// user message and archival report, and the full transcript including this round. The
// state manager writes final_illustration.png (deleting latest.png) and re-materializes
// session_events.json + total_cost.json, as for any completed run.
// =============================================================================

// ⚠️ .item does not exist in "Run Once for All Items" mode, and Final outcome runs once
//    per gate round, so take its LAST run (same helper as Archive Scaffolding).
const latestRun = (nodeName) => {
    let latest = null;
    for (let run = 0; run < 50; run++) {
        let data;
        try { data = $(nodeName).all(0, run); }
        catch (e) { break; }
        if (data && data.length) latest = data[data.length - 1].json;
    }
    return latest;
};

const rebuilt = $("Resume: Rebuild State").first().json;
const load = $("Resume: Load Job").first().json;
const { config, session_state, session_events: events = [] } = items[0].json;
// Human outcome (the scaffold gate) only runs in a resumed job during a redraw, so a stop
// there is "abort" too.
const scaffoldStop = (latestRun("Human outcome") || {}).human_action === "abort";
const action = scaffoldStop ? "abort" : (latestRun("Final outcome") || {}).human_action;
const previous = load.resume.previous || {};
const now = new Date().toISOString();

const note = {
    author: "final_gate",
    task: "resume_final_gate",
    status: "ok",
    parts: [{ text: scaffoldStop
        ? "The human reviewer stopped the base-diagram redraw. The job keeps the illustration and report it had before the round."
        : action === "abort"
        ? "The human reviewer stopped the resumed review round. The job keeps the illustration and report it had before the round."
        : "The resumed review round ended without a repaint. The job keeps the illustration and report it had before the round." }],
    timestamp: now,
    model: "none",
    cost: 0,
};
// Same run_settings record Send Final Broadcast writes, so a resume of THIS job finds
// the style without inferring it (see "Resume: Load Job").
const settings = {
    author: "run_settings",
    task: "run_settings",
    status: "ok",
    parts: [{ text: JSON.stringify({
        style_preference: config.style_preference ?? null,
        max_text_tier: config.maximum_text_tier ?? null,
        max_image_tier: config.maximum_image_tier ?? null,
    }) }],
    timestamp: now,
    model: "none",
    cost: 0,
};
const transcript = [...events, note, settings];
const totalCost = Number(transcript.reduce((sum, ev) => sum + (ev.cost || 0), 0).toFixed(6));

// ⚠️ NEVER include `config` (contains api_keys): the listener merges this payload into
//    the job doc.
await this.helpers.httpRequest({
    method: "POST",
    url: config.gui_webhook_url,
    headers: { "Content-Type": "application/json" },
    json: true,
    timeout: 30000,
    body: {
        job_id: config.job_id,
        status: "completed",
        timestamp: now,
        phase_id: "-",
        agent_id: "-",
        task_id: "-",
        total_cost: totalCost,
        base64_img_string: rebuilt.resume_final_b64,
        base64_img_string_mime: rebuilt.resume_final_mime || "image/png",
        events: [note, settings],
        session_events: transcript,
        user_message: previous.user_message,
        archival_report: previous.archival_report,
        generation_successful: previous.generation_successful ?? true,
        latest_description: previous.latest_description ?? session_state.latest_description ?? null,
        original_query: session_state.original_query ?? null,
        human_review: { gate: "final", stage: "closed", last_action: action === "abort" ? "abort" : "kept_previous" },
    },
});

return [{ json: {
    status: "Resume closed: previous result kept",
    job_id: config.job_id,
    human_action: action,
    total_cost: totalCost,
} }];

// =============================================================================
// 🔁 RESUME: PREPARE REDRAW  (Code node, "Run Once for All Items")
//
// Resumed jobs only. Reached from "Resume: redraw scaffold?" when the Final Gatekeeper's
// resume variant (final_review_*_resume) set redraw_scaffold: the human confirmed a change
// to the base diagram itself. Sets the run up to go back through Phase 3:
//
//   1. Restores the description Phase 3 originally worked from. Phase 4's product_designer
//      rewrites latest_description (adding invented brands/themes), and Phase 3 was built
//      never to see that. The Phase 3 version is simply the last latest_description written
//      by image_detail_planner (merge_plans / review_description, or an earlier
//      amend_description), so it's recovered from the transcript and works on any job.
//      Falls back to the current value if the transcript has none.
//   2. Clears gate flags left over from the first pass, so the redo's scaffold gate and the
//      next final gate decide from fresh answers.
//   3. Arms the painting directives exactly as "Final corrections → reset retries" does, so
//      painting changes from the same request still reach the artist after the redraw.
//   4. Posts a human_gate "scaffold_redo" marker: the coding team and inspection manager see
//      it in their history, and "cfg human review" counts scaffold-review turns after it.
//
// Next: cfg amend description → image_detail_planner - amend_description → Route Workflow3,
// i.e. the normal Phase 3 from the original route onward.
// =============================================================================

const { config, session_state, session_events: events = [] } = items[0].json;
if (!config || !session_state) throw new Error("Resume: Prepare Redraw — missing config / session_state");

const changes = String(session_state.scaffold_changes || "").trim();
if (!changes) throw new Error("Resume: a redraw was requested but scaffold_changes is empty");

// 1. The description Phase 3 worked from.
let phase3Description = null;
for (const ev of events) {
    if (ev.author !== "image_detail_planner" || ev.status === "error") continue;
    const text = (ev.parts || []).filter(p => typeof p.text === "string" && !p.thought).map(p => p.text).join("");
    try {
        const result = JSON.parse(text);
        if (result && typeof result.latest_description === "string" && result.latest_description) {
            phase3Description = result.latest_description;
        }
    } catch (e) { /* not a JSON turn */ }
}

const state = { ...session_state, latest_description: phase3Description || session_state.latest_description };

// 2. Stale gate flags from the first pass.
for (const k of ["redraw_scaffold", "scaffold_acceptable_as_is", "understanding_confirmed",
                 "user_wants_to_stop", "reply_to_human", "passed_review", "passed_inspection"]) {
    delete state[k];
}

// 3. Painting directives, as "Final corrections → reset retries" sets them.
const lib = config.retry_directive_library || {};
state.image_retry_directives = lib.plan_finishing_human || "";
state.image_human_priority_directives = lib.final_review_human || "";

// 4. Marker.
const now = new Date().toISOString();
const marker = {
    author: "human_gate",
    task: "scaffold_redo",
    status: "ok",
    parts: [{ text: `At the final review of this reopened job, the human asked for the base diagram itself to be redrawn, and confirmed it. Requested changes:\n${changes}\nThe diagram description is being amended to match, then the base diagram is planned, coded and inspected again.` }],
    timestamp: now,
    model: "none",
    cost: 0,
};

if (config.enable_gui_logging === true && config.gui_webhook_url) {
    await this.helpers.httpRequest({
        method: "POST",
        url: config.gui_webhook_url,
        headers: { "Content-Type": "application/json" },
        json: true,
        timeout: 15000,
        body: { job_id: config.job_id, status: "running", timestamp: now, phase_id: "3",
                agent_id: "human_gate", task_id: "scaffold_redo", events: [marker] },
    });
}

return [{ json: { config, session_state: state, session_events: [...events, marker] } }];

const results = [];

for (let i = 0; i < items.length; i++) {
  // 1. Force n8n to read the file from disk
  const binaryBuffer = await this.helpers.getBinaryDataBuffer(i, 'data');

  // 2. Convert to Base64
  const base64String = binaryBuffer.toString('base64');
  const mimeType = items[i].binary.data.mimeType;

  // 3. Construct the exact same output JSON to preserve downstream compatibility
  const outputJson = {
    ...items[i].json, 
    base64_img_string: base64String,
    base64_img_string_mime: mimeType
  };

  results.push({ json: outputJson });

  // 4. 📡 GUI PROGRESS BROADCAST (Fire & Forget)
  const config = outputJson.config || {};
  if (config.enable_gui_logging === true && config.gui_webhook_url) {
      try {
          const firestorePayload = {
              job_id: config.job_id, 
              phase_id: outputJson.PHASE_ID || "3", 
              agent_id: "scaffolding_generator", 
              status: "running",
              timestamp: new Date().toISOString(),
              base64_img_string: base64String
          };

          await this.helpers.httpRequest({
              method: 'POST',
              url: config.gui_webhook_url,
              headers: { 'Content-Type': 'application/json' },
              body: firestorePayload,
              json: true,
              timeout: 5000 
          });
      } catch (e) { 
          // Ignore timeouts/errors so the pipeline continues to Phase 4
      }
  }
}

return results;

