// === 🖼️ VIEW BASE64 IMAGE ===
const item = items[0].json;
const base64String = item.base64_img_string;

if (!base64String) {
    throw new Error("No image data found. The Artist agent likely failed to parse the output.");
}

// Default to png, but use dynamic type if available
const mime = item.base64_img_string_mime || "image/png";
const ext = mime.split('/')[1] || "png";

return [{
    json: item, 
    binary: {
        data: {
            data: base64String,
            mimeType: mime,
            fileExtension: ext,
            fileName: `generated_image.${ext}`
        }
    }
}];

// 1. Grab the ADK envelope
const {
  config,
  session_state: sessionState = {},
  session_events: sessionEvents = []
} = items[0].json;

// 2. Normalize the booleans (parsed fields live in session_state now)
const hasMath = sessionState.math_found === true;
const hasVisual = sessionState.image_request_found === true;

// 3. The Decision Logic — payload formatting (problem/description/status) is
//    handled by the per-branch no_model format_* tasks, so we ONLY pick a route.
let validation_route = "neither";
if (hasMath && hasVisual) validation_route = "ready";
else if (hasMath) validation_route = "math_only";
else if (hasVisual) validation_route = "visual_only";

// 4. Envelope through untouched; validation_route rides at top level for the Switch.
return [{
  json: {
    validation_route,
    config,
    session_state: sessionState,
    session_events: sessionEvents
  }
}];

// =============================================================================
// 📦 FINAL BROADCAST CONTRACT — the completion payload for the GUI stack.
// "Phase 6 - Output" carries ONLY { config, session_state, session_events };
// everything else is assembled HERE from direct node references. This node is
// the single source of truth for what ships on completion.
//
// NAMING: the Firestore doc's working transcript (built turn by turn from nodes
// 1 & 3's per-event broadcasts) is `session_events_incremental`. The FINISHED
// transcript — this payload's `session_events` — is what ends up in the bucket
// as {job_id}/session_events.json.
//
// DELIVERABLES and who consumes them:
//   ritel-state-manager/main.py (/update-state → Firestore + GCS bucket):
//    1. job_id                              REQUIRED — Firestore doc key
//    2. status: "completed"                 routes the final image, deletes
//                                           {job_id}/latest.png, and — as a
//                                           terminal status — triggers the listener
//                                           to materialize {job_id}/session_events.json
//                                           from the doc's session_events_incremental
//    3. base64_img_string (+ 4. _mime)      final render → {job_id}/final_illustration.png
//    5. session_events                      one-shot finished transcript. NOT stored
//                                           in the doc (listener pops it): fallback
//                                           transcript source + debug cross-check
//                                           against session_events_incremental
//                                           ("TRANSCRIPT MISMATCH" in Cloud Run
//                                           logs on divergence).
//    6. total_cost                          top-level realtime field; node 3 already
//                                           ships the running total every turn —
//                                           this is the same sum, finalized
//   ritel-frontend/app.py (via the Firestore doc; it renders
//   session_events_incremental — the one-shot copy never reaches the doc):
//    7. user_message                        chat panel (st.info)
//    8. archival_report                     zip download: archival_report.txt
//    9. latest_description                  metadata panel
//   10. original_query                      metadata panel
//   (+ generation_successful, timestamp, and the "-" phase/agent/task markers,
//    which the frontend shows as generic metadata / completion state)
//
//   NOTE: scaffolding is NOT shipped here anymore — "Archive Scaffolding" pins
//   {job_id}/scaffolding.png at the end of Phase 3 (real render or placeholder),
//   and re-sending the same bytes doubled this payload for nothing.
//
// ⚠️ NEVER include `config` (contains api_keys) or api keys in the payload —
//    the listener merges the entire payload into the Firestore job doc.
// ⚠️ LOAD-BEARING, not fire-and-forget (same policy as nodes 1 & 3 now): if this
//    POST fails, Firestore never learns the run completed — no final image, no
//    transcript materialization, a zombie "running" doc — while the workflow
//    would return a phantom "Workflow Complete". So a failure STOPS the run.
// ⚠️ NEVER reach back by name with a bare .first()/.last()/.all(). Those pick the
//    ITEM; the RUN is the second argument, and omitting it lets n8n choose — it
//    resolves against THIS node's run index (0, since this node runs once), so on
//    any retry loop you silently read the FIRST, REJECTED attempt. .item resolves
//    the run correctly but doesn't exist in "Run Once for All Items" mode. Hence
//    latestRun(): walk the runs and keep the last one that produced data.
// =============================================================================

const latestRun = (nodeName) => {
    let latest = null;
    for (let run = 0; run < 50; run++) {   // cap is a sanity guard; real loops max at 3
        let data;
        try { data = $(nodeName).all(0, run); }
        catch (e) { break; }               // past the last run, or node never executed
        if (data && data.length) latest = data[data.length - 1].json;
    }
    return latest;                         // null = node never ran on this path
};

const { config = {}, session_state: ss = {}, session_events: rawEvents = [] } =
    latestRun('Phase 6 - Output') || {};

// === 🏷️ RUN SETTINGS — launch choices baked into the config and otherwise lost ===
// "Resume final review" (Resume: Load Job) reads the LAST run_settings event to rebuild
// the config with the same style. Author "run_settings" is in no agent's history_scope,
// so no agent ever sees it.
const runSettingsEvent = {
    author: "run_settings",
    task: "run_settings",
    status: "ok",
    parts: [{ text: JSON.stringify({
        style_preference: config.style_preference ?? null,
        max_text_tier: config.maximum_text_tier ?? null,
        max_image_tier: config.maximum_image_tier ?? null
    }) }],
    timestamp: new Date().toISOString(),
    model: "none",
    cost: 0
};
const events = [...rawEvents, runSettingsEvent];

// Final render (artist output). Null-safe: nulls if the node never ran.
const artistJson = latestRun('artist - render_final');
const finalRender = {
    img:  artistJson?.base64_img_string || null,
    mime: artistJson?.base64_img_string_mime || null
};

// === 💸 TOTAL COST — sum of per-event model costs in the transcript ===
const totalCost = Number(
    events.reduce((sum, ev) => sum + (ev.cost || 0), 0).toFixed(6)
);

const finalPayload = {
    job_id: config.job_id,
    status: "completed",
    timestamp: new Date().toISOString(),
    phase_id: "-",
    agent_id: "-",
    task_id: "-",
    total_cost: totalCost,
    base64_img_string: finalRender.img,
    base64_img_string_mime: finalRender.mime || "image/png",
    session_events: events,
    events: [runSettingsEvent],       // into the doc's working transcript too
    user_message: ss.user_message ?? null,
    archival_report: ss.archival_report ?? null,
    generation_successful: ss.generation_successful ?? null,
    latest_description: ss.latest_description ?? null,
    original_query: ss.original_query ?? null
};

// Fire the completion payload to the Cloud Run listener
if (config.enable_gui_logging === true && config.gui_webhook_url) {
    try {
        await this.helpers.httpRequest({
            method: 'POST',
            url: config.gui_webhook_url,
            headers: { 'Content-Type': 'application/json' },
            body: finalPayload,
            json: true,
            timeout: 30000   // heaviest POST of the run: final image + full transcript,
                             // and the listener materializes session_events.json
                             // before responding
        });
    } catch (e) {
        throw new Error(`Final broadcast failed — completion NOT persisted: ${e.message}`);
    }
}

return [{ json: {
    status: "Workflow Complete",
    job_id: config.job_id,
    generation_successful: ss.generation_successful ?? null,
    user_message: ss.user_message ?? null,
    latest_description: ss.latest_description ?? null,
    archival_report: ss.archival_report ?? null,
    total_cost: totalCost,
    session_events: events
} }];

