// RUN — with no runIndex n8n resolves the run against THIS node's run index, so if
// "Select Query" ever lands inside a loop we'd silently read run 0 forever.
const latestRun = (nodeName) => {
    let latest = null;
    for (let run = 0; run < 50; run++) {
